CREATE OR REPLACE FUNCTION public.combat_panel_state_v1(p_location uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE adapter text; reason text;
BEGIN
 adapter:=combat_panel_private.location_adapter(p_location);
 reason:=combat_panel_private.access_reason(p_location,adapter);
 IF reason IS NOT NULL THEN RETURN combat_panel_private.blocked(reason); END IF;
 IF adapter='master_v2' THEN RETURN combat_panel_private.master_projection(p_location,p_actor); END IF;
 RETURN combat_panel_private.ordinary_projection(p_location,p_actor);
END $function$

