 THEN RAISE EXCEPTION 'FROZEN43_ROOT_CANDIDATE_CONSTRAINTS';END IF;
 SELECT jsonb_agg(jsonb_build_object('oid',p.oid::bigint,'signature',expected->>'signature','owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'config',to_jsonb(p.proconfig),'secdef',p.prosecdef,'volatility',p.provolatile::text,'language',l.lanname,'source_md5',md5(p.prosrc),'ddl_md5',md5(pg_get_functiondef(p.oid))) ORDER BY p.oid)
