 SELECT jsonb_agg(jsonb_build_object('oid',fn.oid::bigint,'signature',expected->>'signature','owner',pg_get_userbyid(fn.proowner),'acl',fn.proacl::text,'config',to_jsonb(fn.proconfig),'secdef',fn.prosecdef,'volatility',fn.provolatile::text,'language',lang.lanname,'source_md5',md5(fn.prosrc),'ddl_md5',md5(pg_get_functiondef(fn.oid))) ORDER BY fn.oid) INTO actual_headers
 FROM jsonb_array_elements(expected_identities) expected
 LEFT JOIN pg_proc fn ON fn.oid=to_regprocedure(expected->>'signature') AND fn.oid=(expected->>'oid')::oid
 LEFT JOIN pg_language lang ON lang.oid=fn.prolang;
 IF encode(extensions.digest(actual_headers::text,'sha256'),'hex') IS DISTINCT FROM '61c2ce5652e26058125563b66fd153b7949a6f369330858837a62e1fe3af263b'
 THEN RAISE EXCEPTION 'EVENT43_RESULT_ABI_DRIFT';END IF;
 candidate:=ready.canonical_preimage::jsonb;
 FOR operation IN SELECT value FROM jsonb_array_elements(delta) LOOP
 SELECT array_agg(value ORDER BY ordinality) INTO path FROM jsonb_array_elements_text(operation->'path') WITH ORDINALITY;
 candidate:=jsonb_set(candidate,path,operation->'value',true);
 END LOOP;
 candidate:=jsonb_set(candidate,'{recovery}',($RECOVERY${"history_keep": true, "schema_version": "c1266-event-causal-forward-hold/1", "old_body_rollback": false, "code_identity_sha256": "bb9a19ce153ace0c6e652c8d6461c787f59a1f3d736680043fc9d674a5837129", "provider_calls_added": 0}$RECOVERY$::jsonb)||jsonb_build_object('previous_recovery',candidate->'recovery'),false);
 -- Preserve whole JSON string tokens, removing whitespace only outside strings.
 candidate_text:=regexp_replace(candidate::text,$json_re$("(?:[^"\\]|\\.)*")|[[:space:]]+$json_re$,E'\\1','g');
 IF octet_length(candidate_text) NOT BETWEEN 2 AND 262144 OR candidate_text::jsonb IS DISTINCT FROM candidate
 OR jsonb_typeof(candidate)<>'object' OR candidate->>'schema_version' IS DISTINCT FROM 'mission-factory-release-tuple/1'
 OR NOT candidate ?& ARRAY['schema_version','contract','db_core','edge_bundles','ui','config','recovery']
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(candidate) k WHERE k NOT IN('schema_version','contract','db_core','edge_bundles','ui','config','recovery'))
 THEN RAISE EXCEPTION 'EVENT43_ROOT_SIZE_OR_SCHEMA_DRIFT';END IF;
 IF encode(extensions.digest(convert_to(candidate_text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM '9a82654dfee11bd3e27975e50b2b327221f387fcfc4e320c6f8415ca5fedff68'
 OR candidate#>'{db_core,all_function_headers}' IS DISTINCT FROM actual_headers
 THEN RAISE EXCEPTION 'EVENT43_ROOT_COMPOSITION_DRIFT';END IF;
 UPDATE mission_factory_owner.editor_release_readiness rr
 SET canonical_preimage=candidate_text,revision_sha256='9a82654dfee11bd3e27975e50b2b327221f387fcfc4e320c6f8415ca5fedff68',observed_revision_sha256='9a82654dfee11bd3e27975e50b2b327221f387fcfc4e320c6f8415ca5fedff68',
 client_build='mission-factory-admin/2:9a82654dfee11bd3e27975e50b2b327221f387fcfc4e320c6f8415ca5fedff68',independent_review_ref='/private/tmp/tus-c1266-continuity43-20261027/event_uncertain/candidate/EVENT_INTEGRATED_REVIEW.json',updated_at=clock_timestamp()
