 EXECUTE $source_2$CREATE OR REPLACE FUNCTION ninja_book_internal.staff_legacy_media_adoption_v1(p_version uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE rr mission_factory_owner.editor_release_readiness;a ninja_book_internal.legacy_media_adoptions_v1;
 nv public.nb_template_versions;pv public.nb_template_versions;t public.nb_templates;
 b public.nb_mechanical_bindings;pb public.nb_mechanical_bindings;mv public.nb_mechanical_versions;media public.nb_template_media_versions;
BEGIN
 -- Keep ordinary/public qualification unchanged. Only actual Staff or the
 -- existing service authority may read the Staff-only adoption projection.
 IF public.is_staff() IS DISTINCT FROM TRUE THEN
  BEGIN PERFORM mission_ai_board_owner.service_only();EXCEPTION WHEN OTHERS THEN RETURN NULL;END;
 END IF;
 SELECT * INTO rr FROM mission_factory_owner.editor_release_readiness WHERE singleton;
 IF rr.state IS DISTINCT FROM 'enabled' OR rr.scope IS DISTINCT FROM 'staff'
  OR rr.observed_revision_sha256 IS DISTINCT FROM rr.revision_sha256
  OR rr.revision_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(rr.canonical_preimage,'UTF8'),'sha256'),'hex')
  OR rr.staff_guards_verified IS DISTINCT FROM TRUE OR rr.published_assets_verified IS DISTINCT FROM TRUE
  OR rr.canonical_preimage::jsonb#>>'{config,manual_staff,enabled}' IS DISTINCT FROM 'true'
  OR rr.canonical_preimage::jsonb#>>'{config,manual_staff,resource_scope}' IS DISTINCT FROM 'staff_simulation'
  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.runtime_policy pol WHERE pol.singleton AND pol.enabled IS FALSE)
 THEN RETURN NULL;END IF;
 SELECT * INTO a FROM ninja_book_internal.legacy_media_adoptions_v1 WHERE narrative_version_id=p_version;
 IF a.narrative_version_id IS NULL OR a.receipt_sha256 IS DISTINCT FROM ninja_book_internal.json_hash(a.receipt) THEN RETURN NULL;END IF;
 SELECT * INTO nv FROM public.nb_template_versions WHERE id=a.narrative_version_id AND template_id=a.template_id;
 SELECT * INTO pv FROM public.nb_template_versions WHERE id=a.previous_narrative_version_id AND template_id=a.template_id;
 SELECT * INTO t FROM public.nb_templates WHERE id=a.template_id;
 SELECT * INTO b FROM public.nb_mechanical_bindings WHERE id=a.binding_id AND narrative_version_id=nv.id AND narrative_template_id=t.id;
 SELECT * INTO pb FROM public.nb_mechanical_bindings WHERE narrative_version_id=pv.id AND narrative_template_id=t.id;
 SELECT * INTO mv FROM public.nb_mechanical_versions WHERE id=b.mechanical_version_id AND template_id=b.mechanical_template_id;
 SELECT * INTO media FROM public.nb_template_media_versions WHERE id=a.media_id AND template_id=t.id;
 IF nv.id IS NULL OR pv.id IS NULL OR t.id IS NULL OR b.id IS NULL OR pb.id IS NULL OR mv.id IS NULL OR media.id IS NULL
  OR t.lifecycle_state IS DISTINCT FROM 'approved' OR t.deactivated_at IS NOT NULL OR t.current_version_id IS DISTINCT FROM nv.id
  OR nv.review_state IS DISTINCT FROM 'approved' OR nv.supersedes_version_id IS DISTINCT FROM pv.id
  OR nv.approved_at IS NULL OR pv.approved_at IS NULL OR pv.approved_at>=nv.approved_at
  OR nv.content_sha256 IS DISTINCT FROM a.new_content_sha256 OR pv.content_sha256 IS DISTINCT FROM a.previous_content_sha256
  OR nv.skeleton->'identity' IS DISTINCT FROM pv.skeleton->'identity'
  OR ninja_book_internal.json_hash(nv.skeleton->'identity') IS DISTINCT FROM a.identity_sha256
  OR b.lifecycle_state IS DISTINCT FROM 'approved' OR pb.lifecycle_state IS DISTINCT FROM 'approved'
  OR (b.mechanical_template_id,b.mechanical_version_id) IS DISTINCT FROM(pb.mechanical_template_id,pb.mechanical_version_id)
  OR mv.profile_kind IS DISTINCT FROM 'legacy' OR mv.review_state IS DISTINCT FROM 'approved'
  OR media.lifecycle_state IS DISTINCT FROM 'approved' OR media.active IS DISTINCT FROM TRUE
  OR media.superseded_by_media_id IS NOT NULL OR media.kind IS DISTINCT FROM 'canonical_full_body'
  OR media.sha256 IS DISTINCT FROM media.verified_sha256 OR media.sha256 IS DISTINCT FROM a.media_sha256
  OR NOT EXISTS(SELECT 1 FROM storage.objects obj WHERE obj.bucket_id=media.bucket AND obj.name=media.object_path
   AND obj.metadata->>'mimetype'=media.mime_type AND (obj.metadata->>'size')::bigint=media.bytes)
 THEN RETURN NULL;END IF;
 IF a.receipt->>'original_narrative_approved_by' IS DISTINCT FROM nv.approved_by::text
  OR (a.receipt->>'original_narrative_approved_at')::timestamptz IS DISTINCT FROM nv.approved_at
  OR NOT EXISTS(SELECT 1 FROM ninja_book_internal.admin_requests req
   WHERE req.operation='nb_admin_template_approve' AND req.actor_id=nv.approved_by AND req.response->>'version_id'=nv.id::text)
 THEN RETURN NULL;END IF;
 IF a.approval_kind='admin_approval' AND NOT EXISTS(SELECT 1 FROM ninja_book_internal.admin_requests req
  WHERE req.request_key=a.approval_request_key AND req.operation='nb_admin_template_approve'
   AND req.actor_id=a.actor_id AND req.response->'media_adoption'=a.receipt)
 THEN RETURN NULL;END IF;
 IF media.template_version_id IS DISTINCT FROM pv.id AND NOT EXISTS(
  SELECT 1 FROM ninja_book_internal.legacy_media_adoptions_v1 prior
   WHERE prior.narrative_version_id=pv.id AND prior.template_id=t.id AND prior.media_id=media.id
    AND prior.new_content_sha256=pv.content_sha256 AND prior.identity_sha256=a.identity_sha256 AND prior.media_sha256=media.sha256 AND prior.receipt_sha256=ninja_book_internal.json_hash(prior.receipt))
 THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('schema_version','staff-legacy-media-qualification/1','narrative_version_id',nv.id,
  'template_id',t.id,'binding_id',b.id,'media_id',media.id,'asset_version',media.asset_version,'sha256',media.sha256,'receipt_sha256',a.receipt_sha256);
END
