 EXECUTE $source_3$-- Source fragment for the reviewed integrated installer, not a standalone apply.
DO $media_recovery43$
DECLARE target jsonb;nv public.nb_template_versions;before_v jsonb;before_media text;after_media text;receipt jsonb;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'NB_MEDIA_RECOVERY_OWNER' USING ERRCODE='42501';END IF;
 SELECT ninja_book_internal.json_hash(jsonb_agg(to_jsonb(m) ORDER BY m.id)) INTO before_media FROM public.nb_template_media_versions m
 WHERE m.id IN('b18688be-4083-404b-a029-63f6a8d2af23'::uuid,'0527e9f3-ed60-4380-9d67-516faca17f3d'::uuid);
 FOR target IN SELECT value FROM jsonb_array_elements('[
  {"template":"2317301f-2144-4a13-99d2-b6be0b9e75c9","version":"2f36fd21-2651-4c91-9ec6-fbfc0148d058","previous":"b475a066-3d9f-4363-8c4c-49d4ffd3f789","content_sha":"78d1dd5f0e34ef1f5e64e4235cb825e8be1bc127e0f0e2a01d15e921ef9ea6cb","identity_sha":"4bc7cb8cea6a43d51af729697376a0d379fd9997191893bcdb79ca79f473bf0c","approval_request":"9acae79d-e858-40b0-bd88-3b1daabc4cdb","binding":"4d22fa2c-4dbf-4d31-b368-e29c479d2885","media":"b18688be-4083-404b-a029-63f6a8d2af23","media_sha":"ad92896adb267b85651bb9f8f3e84d38e875be3717acc80b1e63213a8863ff28"},
  {"template":"61e18860-8c64-4740-8285-6b03fc343212","version":"40853292-9f6e-4650-8fe7-e8bdba3bcb7d","previous":"03c1e7d8-d5f3-4725-9465-79d9ea0d14b2","content_sha":"863c00795d6758709a84ba1c2a683513de683f81dc9cb55addfe95733d61309a","identity_sha":"54bd3f3b66c3efc64a152f2702d9913229e47ab4ccc931a2b960932fcf13b44c","approval_request":"b87910bd-71e1-45fc-9356-441d26498c38","binding":"0f8190be-3bbf-4fac-82ec-757360e9e740","media":"0527e9f3-ed60-4380-9d67-516faca17f3d","media_sha":"4134013a1dea6b67cebde93867e3dc5161ac4406b05379f2e869c48a2db86898"}
 ]'::jsonb) LOOP
  SELECT * INTO STRICT nv FROM public.nb_template_versions WHERE id=(target->>'version')::uuid AND template_id=(target->>'template')::uuid FOR SHARE;
  IF nv.review_state IS DISTINCT FROM 'approved' OR nv.supersedes_version_id::text IS DISTINCT FROM target->>'previous'
   OR nv.content_sha256 IS DISTINCT FROM target->>'content_sha'
   OR ninja_book_internal.json_hash(nv.skeleton->'identity') IS DISTINCT FROM target->>'identity_sha'
   OR NOT EXISTS(SELECT 1 FROM public.nb_templates t WHERE t.id=nv.template_id AND t.current_version_id=nv.id AND t.lifecycle_state='approved')
   OR NOT EXISTS(SELECT 1 FROM ninja_book_internal.admin_requests q WHERE q.request_key=(target->>'approval_request')::uuid
    AND q.operation='nb_admin_template_approve' AND q.response->>'version_id'=nv.id::text AND q.actor_id=nv.approved_by)
  THEN RAISE EXCEPTION 'NB_MEDIA_RECOVERY_SOURCE_DRIFT' USING ERRCODE='40001';END IF;
  before_v:=to_jsonb(nv);
  receipt:=ninja_book_internal.append_legacy_media_adoption_v1(nv.template_id,nv.id,NULL,NULL);
  IF receipt IS NULL OR receipt->>'binding_id' IS DISTINCT FROM target->>'binding'
   OR receipt->>'media_id' IS DISTINCT FROM target->>'media' OR receipt->>'media_sha256' IS DISTINCT FROM target->>'media_sha'
   OR receipt->>'approval_kind' IS DISTINCT FROM 'system_migration' OR receipt->'actor_id' IS DISTINCT FROM 'null'::jsonb
   OR before_v IS DISTINCT FROM(SELECT to_jsonb(v) FROM public.nb_template_versions v WHERE v.id=nv.id)
  THEN RAISE EXCEPTION 'NB_MEDIA_RECOVERY_RECEIPT_DRIFT' USING ERRCODE='55000';END IF;
 END LOOP;
 SELECT ninja_book_internal.json_hash(jsonb_agg(to_jsonb(m) ORDER BY m.id)) INTO after_media FROM public.nb_template_media_versions m
 WHERE m.id IN('b18688be-4083-404b-a029-63f6a8d2af23'::uuid,'0527e9f3-ed60-4380-9d67-516faca17f3d'::uuid);
 IF before_media IS DISTINCT FROM after_media THEN RAISE EXCEPTION 'NB_MEDIA_RECOVERY_ORIGINAL_ASSET_MUTATED' USING ERRCODE='55000';END IF;
 RAISE NOTICE 'NB_MEDIA_RECOVERY_COMPLETED two version adoptions, original assets unchanged';
END
