 EXECUTE $source_5$CREATE OR REPLACE FUNCTION public.nb_media_resolve(p_template_version uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
select coalesce((
  select pg_catalog.jsonb_build_object(
    'schema_version','ninja-book-media-consumer/1.0','fallback',null,
    'image',pg_catalog.jsonb_build_object(
      'media_id',m.id,'asset_id',m.asset_id,'kind',m.kind,'public_url',m.public_url,
      'sha256',m.sha256,'mime_type',m.mime_type,'width_px',m.width_px,
      'height_px',m.height_px,'alt_text',m.alt_text))
  from public.nb_template_media_versions m
  join public.nb_templates t on t.id=m.template_id
  join public.nb_template_versions v on v.id=m.template_version_id and v.template_id=m.template_id
  where m.template_version_id=p_template_version and t.current_version_id=p_template_version
    and t.lifecycle_state='approved' and v.review_state='approved'
    and m.lifecycle_state='approved' and m.active and m.superseded_by_media_id is null
),(
 select pg_catalog.jsonb_build_object('schema_version','ninja-book-media-consumer/1.0','fallback',null,
  'image',pg_catalog.jsonb_build_object('media_id',m.id,'asset_id',m.asset_id,'kind',m.kind,'public_url',m.public_url,
   'sha256',m.sha256,'mime_type',m.mime_type,'width_px',m.width_px,'height_px',m.height_px,'alt_text',m.alt_text))
 from ninja_book_internal.staff_legacy_media_adoption_v1(p_template_version) q
 join public.nb_template_media_versions m on m.id=nullif(q->>'media_id','')::uuid
 where q IS NOT NULL
),'{"schema_version":"ninja-book-media-consumer/1.0","fallback":"no_image","image":null}'::jsonb)
$function$
