 EXECUTE $source_6$CREATE OR REPLACE FUNCTION mission_surface_internal.safe_media(p_version uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;adoption jsonb; mid uuid; av integer;
begin
 r:=public.nb_media_resolve(p_version);
 if r->>'schema_version'<>'ninja-book-media-consumer/1.0' then raise exception 'MISSION_SURFACE_MEDIA_DRIFT';end if;
 if r->>'fallback'='no_image' or r->'image' is null then raise exception 'MISSION_SURFACE_MEDIA_REQUIRED';end if;
 mid:=nullif(r#>>'{image,media_id}','')::uuid;
 select asset_version into av from public.nb_template_media_versions where id=mid and template_version_id=p_version and active and lifecycle_state='approved';
 if not found then
  adoption:=ninja_book_internal.staff_legacy_media_adoption_v1(p_version);
  IF adoption IS NULL OR adoption->>'media_id' IS DISTINCT FROM mid::text
   THEN raise exception 'MISSION_SURFACE_MEDIA_DRIFT';END IF;
  av:=(adoption->>'asset_version')::integer;
 end if;
 return jsonb_build_object('media_id',mid,'asset_version',av,'sha256',r#>>'{image,sha256}',
  'alt_text',r#>>'{image,alt_text}','crop',null);
end$function$
