      ||!['issued','replayed','existing_work'].includes(tick.state)
      ||tick.source_revision!==body.source_revision
      ||!object(tick.progress)
      ||tick.progress.schema_version!=='mission-generic-progress/1'
      ||tick.progress.master_session_id!==body.master_session_id)
